"""Nederlands — sira (sira_001 … sira_150)."""

T = {
"sira_001": ("In welke stad werd de Profeet Muhammad ﷺ geboren?", ["Mekka", "Medina", "Ta'if", "Jeruzalem"], "De Profeet Muhammad ﷺ werd geboren in Mekka, in de Hidjaz."),
"sira_002": ("Hoe heet het geboortejaar van de Profeet ﷺ, gekenmerkt door de gebeurtenis van de olifant?", ["Het Jaar van de Olifant", "Het Jaar van de Overwinning", "Het Jaar van de Kameel", "Het Jaar van het Licht"], "De gebeurtenis van de olifant, waarbij Allah de Ka'ba beschermde, wordt verteld in soera Al-Fil."),
"sira_003": ("Hoe heette de eerste vrouw van de Profeet ﷺ?", ["Khadija", "'Aisha", "Hafsa", "Zaynab"], "Khadija bint Khuwaylid was de eerste vrouw van de Profeet ﷺ en de eerste persoon die in zijn boodschap geloofde."),
"sira_004": ("In welke grot ontving de Profeet ﷺ de eerste openbaring?", ["De grot Hira", "De grot Thawr", "De grot van de Metgezellen", "De grot Uhud"], "De eerste openbaring vond plaats in de grot Hira, op de Jabal an-Nur bij Mekka."),
"sira_005": ("Welke engel bracht de openbaring aan de Profeet ﷺ?", ["Jibril (Gabriël)", "Mika'il (Michaël)", "Israfil", "Malik"], "De Koran vermeldt uitdrukkelijk dat Jibril de openbaring bracht met Allahs toestemming."),
"sira_006": ("Hoe heet de migratie van de Profeet ﷺ en zijn metgezellen van Mekka naar Medina?", ["Al-Hijra", "Al-Isra", "Al-Mi'raj", "Al-Fath"], "Al-Hijra verwijst naar de historische migratie naar Medina, het beginpunt van de islamitische kalender."),
"sira_007": ("Naar welke stad migreerden de Profeet ﷺ en Abu Bakr?", ["Medina", "Ta'if", "Damascus", "Jeruzalem"], "De Profeet ﷺ en Abu Bakr migreerden van Mekka naar Medina (toen Yathrib genoemd)."),
"sira_008": ("De Koran beschrijft een metgezel als «de tweede van twee, toen zij in de grot waren» tijdens de Hijra. Wie was dat?", ["Abu Bakr", "'Umar", "'Uthman", "'Ali"], "De Koran verwijst naar Abu Bakr, die de Profeet ﷺ tijdens de Hijra vergezelde in de grot Thawr."),
"sira_009": ("In welke slag, genoemd in de Koran, versloeg een klein moslimleger een veel grotere macht?", ["De slag bij Badr", "De slag bij Uhud", "De slag van de Gracht", "De slag bij Hunayn"], "Bij Badr schonk Allah een kleine groep gelovigen de overwinning op een veel groter leger."),
"sira_010": ("Hoe heet de grotendeels vreedzame terugkeer van de Profeet ﷺ en zijn metgezellen naar Mekka?", ["De verovering van Mekka (Fath Makkah)", "De slag om Mekka", "Het beleg van Mekka", "De val van Mekka"], "De verovering van Mekka verliep grotendeels vreedzaam, zonder grootschalig bloedvergieten."),
"sira_011": ("Hoe heet de laatste preek die de Profeet ﷺ tegen het einde van zijn leven hield?", ["De Afscheidspreek", "De Preek van Mekka", "De Preek van de Grot", "De Preek van Badr"], "De Afscheidspreek (Khutbat al-Wada') werd gehouden tijdens de laatste bedevaart van de Profeet ﷺ."),
"sira_012": ("In welke maand begon volgens de Koran zijn openbaring?", ["Ramadan", "Muharram", "Rajab", "Dhul-Hijja"], "De Koran zegt dat de Ramadan de maand is waarin de Koran werd geopenbaard."),
"sira_013": ("Wat was het beroep van de Profeet ﷺ voordat hij de openbaring ontving?", ["Koopman/handelaar", "Alleen herder", "Smid", "Schrijver"], "De Profeet ﷺ werkte in de handel, een goed gedocumenteerd feit uit zijn levensbeschrijving."),
"sira_014": ("Welke grootvader van de Profeet ﷺ zorgde voor hem na de dood van zijn moeder?", ["'Abd al-Muttalib", "Abu Talib", "Abu Lahab", "Abu Sufyan"], "'Abd al-Muttalib zorgde voor de jonge Muhammad ﷺ na de dood van zijn moeder Amina."),
"sira_015": ("Welke oom voedde de Profeet ﷺ op na de dood van zijn grootvader?", ["Abu Talib", "Al-'Abbas", "Hamza", "Abu Lahab"], "Abu Talib nam de opvoeding van zijn neef op zich na de dood van 'Abd al-Muttalib."),
"sira_016": ("Hoe heet de nachtelijke reis van de Profeet ﷺ van Mekka naar Jeruzalem, genoemd in de Koran?", ["Al-Isra", "Al-Hijra", "Al-Fath", "Al-Ghazwa"], "Soera Al-Isra opent met de beschrijving van deze wonderbaarlijke nachtelijke reis."),
"sira_017": ("Welke dochter van de Profeet ﷺ trouwde met 'Ali ibn Abi Talib?", ["Fatima", "Zaynab", "Ruqayya", "Umm Kulthum"], "Fatima, dochter van de Profeet ﷺ en Khadija, trouwde met 'Ali ibn Abi Talib: een breed vaststaand feit."),
"sira_018": ("Welke maand markeert het begin van het islamitische kalenderjaar, verwijzend naar de Hijra?", ["Muharram", "Ramadan", "Shawwal", "Dhul-Qa'da"], "De islamitische kalender begint met de maand Muharram, verwijzend naar het jaar van de Hijra."),
"sira_019": ("Wie was de eerste muezzin van de islam, door de Profeet ﷺ gekozen om tot het gebed op te roepen?", ["Bilal ibn Rabah", "Abu Bakr", "'Umar ibn al-Khattab", "Salman al-Farisi"], "Bilal, met zijn mooie stem, werd gekozen als eerste muezzin van de islam."),
"sira_020": ("Welke was de eerste moskee die de Profeet ﷺ stichtte bij aankomst nabij Medina?", ["De moskee van Quba", "De Al-Haram-moskee", "De Al-Aqsa-moskee", "De moskee van de twee qibla's"], "Bij aankomst in Quba, aan de poorten van Medina, stichtte de Profeet ﷺ daar de eerste moskee."),
"sira_021": ("Hoe heette de moeder van de Profeet ﷺ?", ["Amina", "Khadija", "Halima", "Fatima"], "Amina bint Wahb was de moeder van de Profeet ﷺ; Halima was zijn voedster."),
"sira_022": ("Hoe heette de vader van de Profeet ﷺ, die vóór zijn geboorte overleed?", ["'Abdullah", "Abu Talib", "'Abd al-Muttalib", "Hamza"], "'Abdullah, zoon van 'Abd al-Muttalib, overleed voordat zijn zoon Muhammad ﷺ werd geboren."),
"sira_023": ("Welke bijnaam gaven de Mekkanen de Profeet ﷺ vóór de openbaring, om zijn eerlijkheid?", ["Al-Amin (de betrouwbare)", "Al-Faruq", "As-Siddiq", "Sayf Allah"], "Al vóór de openbaring werd hij al-Amin genoemd: de mensen vertrouwden hem hun bezittingen toe."),
"sira_024": ("In welk jaar van de Hijra vond de verovering van Mekka plaats?", ["Jaar 8", "Jaar 2", "Jaar 5", "Jaar 10"], "In het jaar 8 na de Hijra trok de Profeet ﷺ Mekka vrijwel zonder strijd binnen en vergaf hij de bewoners."),
"sira_025": ("In welk jaar van de Hijra verrichtte de Profeet ﷺ zijn Afscheidsbedevaart?", ["Jaar 10", "Jaar 6", "Jaar 8", "Jaar 12"], "De Afscheidsbedevaart vond plaats in het jaar 10 na de Hijra; de Profeet ﷺ hield daar zijn laatste preek."),
"sira_026": ("Hoeveel dochters had de Profeet ﷺ?", ["4", "1", "2", "7"], "Zaynab, Ruqayya, Umm Kulthum en Fatima: de vier dochters van de Profeet ﷺ."),
"sira_027": ("Hoe heten de mensen van Medina die de geëmigreerde moslims verwelkomden en hielpen?", ["De Ansar (de Helpers)", "De Muhajirun", "De Quraysh", "De Tabi'un"], "De Ansar, «de Helpers», deelden hun huizen en bezittingen met hun geëmigreerde broeders."),
"sira_028": ("Hoe heten de moslims die Mekka verlieten om naar Medina te emigreren?", ["De Muhajirun (de Emigranten)", "De Ansar", "De Hunafa'", "De Ghuzat"], "De Muhajirun lieten huis en haard in Mekka achter om hun geloof te behouden."),
"sira_029": ("In welke maand vond de slag bij Badr plaats?", ["Ramadan", "Muharram", "Dhul-Hijja", "Rajab"], "De slag bij Badr vond plaats tijdens de Ramadan, in het jaar 2 na de Hijra."),
"sira_030": ("Naar welke stad baden de moslims voordat de qibla naar de Ka'ba werd gericht?", ["Jeruzalem (Bayt al-Maqdis)", "Medina", "Ta'if", "Damascus"], "De moslims baden eerst richting Bayt al-Maqdis; daarna gebood Allah zich naar de Heilige Moskee te wenden (Koran 2:142-144)."),
"sira_031": ("Tot welke stam behoorde de Profeet Muhammad ﷺ?", ["Quraysh", "De Aws", "De Khazraj", "Thaqif"], "Een hele soera draagt de naam van zijn stam: Quraysh."),
"sira_032": ("Uit welke clan van Quraysh kwam de Profeet ﷺ?", ["Banu Hashim", "Banu Umayya", "Banu Makhzum", "Banu Tamim"], "De Profeet ﷺ behoorde tot de Banu Hashim, de clan van zijn overgrootvader Hashim."),
"sira_033": ("Hoe heette de voedster die de Profeet ﷺ in de woestijn zoogde?", ["Halima as-Sa'diyya", "Amina", "Khadija", "Fatima"], "Volgens Mekkaans gebruik werd de zuigeling toevertrouwd aan een bedoeïenenvoedster: Halima as-Sa'diyya."),
"sira_034": ("Welke oom van de Profeet ﷺ, held van Badr, sneuvelde als martelaar bij Uhud?", ["Hamza", "Abu Talib", "Al-'Abbas", "Abu Lahab"], "Hamza ibn 'Abd al-Muttalib vocht bij Badr en werd gedood in de slag bij Uhud."),
"sira_035": ("Welke neef van de Profeet ﷺ, opgegroeid in zijn huis, werd de vierde kalief?", ["'Ali ibn Abi Talib", "Ja'far", "'Aqil", "Al-'Abbas"], "'Ali, zoon van Abu Talib, groeide op bij de Profeet ﷺ en was de vierde rechtgeleide kalief."),
"sira_036": ("Wie was de eerste kalief na de dood van de Profeet ﷺ?", ["Abu Bakr", "'Umar", "'Uthman", "'Ali"], "Abu Bakr as-Siddiq werd gekozen als eerste kalief."),
"sira_037": ("Welke titel draagt Abu Bakr, omdat hij de Profeet ﷺ zonder aarzelen geloofde?", ["As-Siddiq (de Waarachtige)", "Al-Faruq", "Dhun-Nurayn", "Sayf Allah"], "Abu Bakr wordt as-Siddiq genoemd, degene die de waarheid bevestigt en gelooft."),
"sira_038": ("Welke titel draagt 'Umar ibn al-Khattab?", ["Al-Faruq (die waarheid van leugen onderscheidt)", "As-Siddiq", "Dhun-Nurayn", "Al-Amin"], "'Umar wordt al-Faruq genoemd, degene die waarheid van leugen scheidt."),
"sira_039": ("Waarom wordt 'Uthman ibn 'Affan «Dhun-Nurayn» genoemd, de bezitter van twee lichten?", ["Hij trouwde met twee dochters van de Profeet ﷺ, na elkaar", "Hij droeg twee lampen", "Hij leerde de Koran tweemaal uit het hoofd", "Hij maakte twee hijra's"], "'Uthman trouwde met Ruqayya en, na haar dood, met Umm Kulthum, beiden dochters van de Profeet ﷺ."),
"sira_040": ("In welke volgorde volgden de vier rechtgeleide kaliefen elkaar op?", ["Abu Bakr, 'Umar, 'Uthman, 'Ali", "'Ali, 'Umar, Abu Bakr, 'Uthman", "'Umar, Abu Bakr, 'Ali, 'Uthman", "Abu Bakr, 'Ali, 'Umar, 'Uthman"], "Abu Bakr, dan 'Umar, dan 'Uthman, dan 'Ali."),
"sira_041": ("Wie was de eerste persoon die in de boodschap van de Profeet ﷺ geloofde?", ["Khadija, zijn vrouw", "Abu Bakr", "'Ali", "Bilal"], "Khadija geloofde in hem vanaf de eerste openbaring en steunde hem."),
"sira_042": ("Wie kocht Bilal om hem te bevrijden van de martelingen van zijn meester?", ["Abu Bakr", "'Umar", "Hamza", "'Uthman"], "Abu Bakr kocht Bilal en liet hem vrij."),
"sira_043": ("Wie was de eerste martelares van de islam, in Mekka gedood om haar geloof?", ["Sumayya, moeder van 'Ammar", "Asma", "Umm Salama", "Safiyya"], "Sumayya bint Khayyat, moeder van 'Ammar ibn Yasir, werd gedood door Abu Jahl."),
"sira_044": ("Naar welk land vond de eerste emigratie van in Mekka vervolgde moslims plaats?", ["Abessinië (Ethiopië)", "Perzië", "Jemen", "Egypte"], "De eerste emigranten gingen naar Abessinië, naar een rechtvaardige koning."),
"sira_045": ("Hoe werd de koning van Abessinië genoemd die de moslims beschermde en voor wie de Profeet ﷺ het dodengebed in afwezigheid verrichtte?", ["An-Najashi (de Negus)", "Heraclius", "Chosroes", "Al-Muqawqis"], "De Profeet ﷺ kondigde de dood van de Negus aan op de dag zelf en bad met de metgezellen voor hem."),
"sira_046": ("Welke metgezel sprak voor de Negus om de islam uit te leggen?", ["Ja'far ibn Abi Talib", "'Uthman", "Bilal", "Mus'ab ibn 'Umayr"], "Ja'far legde de koning uit wat de Profeet ﷺ onderwees en droeg hem verzen uit soera Maryam voor."),
"sira_047": ("Welke oom van de Profeet ﷺ wordt in de Koran bij naam veroordeeld?", ["Abu Lahab", "Abu Talib", "Al-'Abbas", "Hamza"], "«Mogen de handen van Abu Lahab vergaan, en moge hij vergaan.»"),
"sira_048": ("Hoe heet het jaar waarin de Profeet ﷺ zijn vrouw Khadija en zijn oom Abu Talib verloor?", ["Het Jaar van Verdriet", "Het Jaar van de Olifant", "Het Jaar van de Delegaties", "Het Jaar van de Hongersnood"], "De twee grote steunpilaren van de Profeet ﷺ stierven in hetzelfde jaar, bekend als het Jaar van Verdriet."),
"sira_049": ("In welke stad werd de Profeet ﷺ verjaagd en verwond na zijn oproep tot de islam, voordat hij weigerde de engel van de bergen haar bewoners te laten verpletteren?", ["At-Ta'if", "Medina", "Khaybar", "Tabuk"], "Verworpen in Ta'if weigerde hij haar bewoners te vernietigen, in de hoop dat hun nakomelingen Allah zouden aanbidden."),
"sira_050": ("Welke plicht werd tijdens de Nachtreis en Hemelvaart (Isra en Mi'raj) aan de moslims voorgeschreven?", ["De vijf dagelijkse gebeden", "Het vasten van Ramadan", "De zakat", "De bedevaart"], "De gebeden werden die nacht voorgeschreven, teruggebracht van vijftig naar vijf, met de beloning van vijftig."),
"sira_051": ("Welke boom, aan de uiterste grens, zag de Profeet ﷺ tijdens de Hemelvaart, volgens soera An-Najm?", ["Sidrat al-Muntaha", "De gezegende olijfboom", "De palmboom van Maryam", "De boom van Tuba"], "«Bij Sidrat al-Muntaha», de lotusboom van de uiterste grens."),
"sira_052": ("Hoe heten de eden van trouw die mensen uit Yathrib vóór de Hijra aan de Profeet ﷺ aflegden?", ["De eden van Al-'Aqaba", "Het verdrag van Hudaybiyya", "De eed van de boom", "De Grondwet van Medina"], "Mensen uit Yathrib zwoeren de Profeet ﷺ trouw bij Al-'Aqaba, nabij Mina, vóór de Hijra."),
"sira_053": ("Welke metgezel zond de Profeet ﷺ vóór de Hijra naar Yathrib om de islam te onderwijzen?", ["Mus'ab ibn 'Umayr", "Bilal", "Abu Hurayra", "Khalid ibn al-Walid"], "Mus'ab ibn 'Umayr was de eerste gezant naar Yathrib en onderwees de Koran aan de nieuwe moslims."),
"sira_054": ("Wie sliep in het bed van de Profeet ﷺ in de nacht dat hij vertrok voor de Hijra?", ["'Ali ibn Abi Talib", "Abu Bakr", "Zayd ibn Haritha", "Bilal"], "'Ali nam zijn plaats in het bed in om de bewakers te misleiden, en gaf daarna de in bewaring gegeven goederen aan de Mekkanen terug."),
"sira_055": ("In welke grot verborgen de Profeet ﷺ en Abu Bakr zich tijdens de Hijra?", ["De grot Thawr", "De grot Hira", "De grot Uhud", "De grot van Ta'if"], "Zij verborgen zich drie dagen in de grot Thawr, ten zuiden van Mekka."),
"sira_056": ("Welke dochter van Abu Bakr bracht proviand naar de grot en kreeg de bijnaam «zij van de twee gordels»?", ["Asma", "'Aisha", "Umm Kulthum", "Umm Ruman"], "Asma scheurde haar gordel in tweeën om de proviand vast te binden: vandaar «Dhat an-Nitaqayn»."),
"sira_057": ("Wat gebeurde er met Suraqa, die de Profeet ﷺ tijdens de Hijra achtervolgde?", ["Zijn paard zakte in de grond weg, en hij vroeg om veiligheid", "Hij haalde de Profeet ﷺ in", "Hij verdwaalde in de woestijn", "Hij werd ziek"], "De poten van zijn paard zakten in de aarde weg; Suraqa vroeg om een vrijgeleide en vertrok zonder kwaad te doen."),
"sira_058": ("Wat was de oude naam van Medina, genoemd in de Koran?", ["Yathrib", "Tayba", "Khaybar", "Bakka"], "«O mensen van Yathrib…», zegt de Koran, terugblikkend op de slag van de bondgenoten."),
"sira_059": ("Hoe heette de kameelmerrie van de Profeet ﷺ, die bij Hudaybiyya knielde?", ["Al-Qaswa", "Al-Buraq", "Ad-Duldul", "Al-'Adba"], "Bij Hudaybiyya knielde Al-Qaswa; de Profeet ﷺ zei: «Degene die de olifant tegenhield, heeft haar tegengehouden.»"),
"sira_060": ("Wat stelde de Profeet ﷺ in tussen de Muhajirun en de Ansar bij aankomst in Medina?", ["Broederschap, in paren", "Een belasting", "Een leger", "Een markt"], "Hij maakte de emigranten en de helpers tot broeders, elke Muhajir gekoppeld aan een broeder uit de Ansar."),
"sira_061": ("Hoe heet het document waarmee de Profeet ﷺ de betrekkingen tussen de gemeenschappen van Medina regelde?", ["De Sahifa (Grondwet) van Medina", "Het verdrag van Hudaybiyya", "Het pact van Ta'if", "Het handvest van Quba"], "De Sahifa legde de rechten en plichten vast van de moslims en de andere stammen van Medina."),
"sira_062": ("Hoe werden de arme metgezellen genoemd die in de moskee van de Profeet ﷺ woonden?", ["Ahl as-Suffa (de mensen van de bank)", "De Muhajirun", "De Ansar", "De Hawariyyun"], "Abu Hurayra vertelt dat hij tot de mensen van de Suffa behoorde, gevoed door de Profeet ﷺ."),
"sira_063": ("Hoeveel jaar na de Hijra vond de slag bij Badr plaats?", ["Twee", "Vijf", "Acht", "Tien"], "Badr werd uitgevochten in het jaar 2 na de Hijra, tijdens de Ramadan."),
"sira_064": ("Hoeveel engelen beloofde Allah als versterking te zenden aan de gelovigen bij Badr?", ["Duizend", "Honderd", "Tien", "Honderdduizend"], "«Ik zal jullie versterken met duizend engelen, de een na de ander.»"),
"sira_065": ("Welke fout van de boogschutters bij Uhud deed de slag kantelen?", ["Zij verlieten de heuvel ondanks het bevel van de Profeet ﷺ", "Zij schoten te vroeg", "Zij vielen in slaap", "Zij liepen over"], "De Profeet ﷺ had de boogschutters bevolen niet te bewegen; de meesten daalden af voor de buit en de vijandelijke ruiterij omsingelde hen."),
"sira_066": ("Nabij welke stad ligt de berg Uhud?", ["Medina", "Mekka", "Ta'if", "Jeruzalem"], "De berg Uhud ligt ten noorden van Medina; de slag vond plaats aan zijn voet."),
"sira_067": ("Welke metgezel stelde voor een gracht te graven om Medina tegen de bondgenoten te verdedigen?", ["Salman al-Farisi", "Bilal", "Abu Dharr", "Suhayb"], "Salman de Pers stelde de gracht voor, een tactiek die in Perzië bekend was."),
"sira_068": ("Onder welke andere naam is de slag van de Gracht bekend, naar de soera die erover spreekt?", ["De slag van de Bondgenoten (Al-Ahzab)", "De slag bij Badr", "De slag bij Hunayn", "De slag bij Mu'ta"], "Soera Al-Ahzab herinnert aan de verbonden legers die Medina belegerden en de wind die tegen hen werd gezonden."),
"sira_069": ("Hoe heet de eed die onder een boom bij Hudaybiyya werd afgelegd, waarover Allah zegt dat Hij tevreden was?", ["Bay'at ar-Ridwan", "Bay'at al-'Aqaba", "Bay'at an-Nisa", "Bay'at al-Fath"], "«Allah was tevreden met de gelovigen toen zij jou trouw zwoeren onder de boom.»"),
"sira_070": ("Welke soera opent met «Wij hebben jou een duidelijke overwinning geschonken», geopenbaard na het verdrag van Hudaybiyya?", ["Al-Fath", "An-Nasr", "Al-Anfal", "At-Tawba"], "«Voorwaar, Wij hebben jou een duidelijke overwinning geschonken»: soera Al-Fath."),
"sira_071": ("In welk jaar van de Hijra werd het verdrag van Hudaybiyya gesloten?", ["6 na de Hijra", "2 na de Hijra", "8 na de Hijra", "10 na de Hijra"], "Het verdrag van Hudaybiyya werd in het jaar 6 na de Hijra gesloten tussen de moslims en Quraysh."),
"sira_072": ("Welke Byzantijnse keizer ontving de brief van de Profeet ﷺ met de uitnodiging tot de islam en ondervroeg Abu Sufyan over hem?", ["Heraclius", "Nero", "Constantijn", "Justinianus"], "Heraclius ondervroeg Abu Sufyan over de Profeet ﷺ na ontvangst van zijn brief."),
"sira_073": ("Aan wie overhandigde de Profeet ﷺ de banier bij Khaybar, nadat hij had gezegd: «Morgen geef ik hem aan een man van wie Allah en Zijn Boodschapper houden»?", ["'Ali ibn Abi Talib", "Abu Bakr", "'Umar", "Sa'd ibn Abi Waqqas"], "Hij riep 'Ali, die last had van zijn ogen; hij bracht zijn speeksel aan, genas hem en gaf hem de banier."),
"sira_074": ("Welke drie bevelhebbers sneuvelden na elkaar in de slag bij Mu'ta?", ["Zayd ibn Haritha, Ja'far ibn Abi Talib en 'Abdullah ibn Rawaha", "Hamza, Mus'ab en Sa'd", "Abu Bakr, 'Umar en 'Uthman", "Bilal, Salman en Suhayb"], "De Profeet ﷺ kondigde in Medina aan: «Zayd nam de banier en sneuvelde, daarna Ja'far, daarna Ibn Rawaha… toen nam een zwaard van Allah hem.»"),
"sira_075": ("Welke metgezel noemde de Profeet ﷺ «een zwaard onder de zwaarden van Allah»?", ["Khalid ibn al-Walid", "'Ali", "Hamza", "Abu 'Ubayda"], "Bij Mu'ta nam «een zwaard onder de zwaarden van Allah», Khalid ibn al-Walid, de banier en redde het leger."),
"sira_076": ("Wat deed de Profeet ﷺ met de afgoden rond de Ka'ba bij de verovering van Mekka?", ["Hij wierp ze omver terwijl hij reciteerde «De waarheid is gekomen en de leugen is verdwenen»", "Hij verkocht ze", "Hij nam ze mee naar Medina", "Hij liet ze staan"], "Hij sloeg met zijn stok tegen de afgoden en zei: «De waarheid is gekomen en de leugen is verdwenen.»"),
"sira_077": ("Wie riep op tot het gebed vanaf de top van de Ka'ba op de dag dat Mekka werd veroverd?", ["Bilal", "Abu Bakr", "'Ali", "'Umar"], "De Profeet ﷺ beval Bilal op de Ka'ba te klimmen en tot het gebed op te roepen."),
"sira_078": ("Wat zei de Profeet ﷺ op de dag van de verovering tegen de verslagen Mekkanen die hem hadden vervolgd?", ["«Ga, jullie zijn vrij»", "«Jullie worden morgen berecht»", "«Verlaat de stad»", "«Betaal losgeld»"], "Hij vergaf hen: «Ga, jullie zijn vrij.»"),
"sira_079": ("In welke slag, genoemd in de Koran, werden de moslims aanvankelijk overrompeld ondanks hun grote aantal?", ["Hunayn", "Badr", "Uhud", "Khaybar"], "«Op de dag van Hunayn behaagde jullie grote aantal jullie, maar het baatte jullie niets.»"),
"sira_080": ("Welke metgezel, die achterbleef bij de expeditie naar Tabuk, bekende eerlijk en werd door een openbaring vergeven?", ["Ka'b ibn Malik", "Abu Dharr", "Anas ibn Malik", "Abu Hurayra"], "Ka'b ibn Malik sprak de waarheid, verdroeg vijftig dagen van uitsluiting, en daarna openbaarde Allah zijn vergeving (9:118)."),
"sira_081": ("Hoe heet het jaar 9 na de Hijra, waarin veel stammen naar Medina kwamen om de islam te omhelzen?", ["Het Jaar van de Delegaties", "Het Jaar van Verdriet", "Het Jaar van de Olifant", "Het Jaar van de Droogte"], "Na de verovering van Mekka stroomden delegaties van Arabische stammen naar Medina."),
"sira_082": ("Waar hield de Profeet ﷺ zijn Afscheidspreek?", ["Bij Arafat", "In Medina", "Op de berg Uhud", "In Ta'if"], "De Afscheidspreek werd gehouden bij Arafat, tijdens de Afscheidsbedevaart."),
"sira_083": ("Welk vers, geopenbaard tijdens de Afscheidsbedevaart, kondigt aan dat de religie vervolmaakt is?", ["«Vandaag heb Ik jullie religie voor jullie vervolmaakt»", "«Lees, in de naam van jouw Heer»", "«Wanneer de overwinning van Allah komt»", "«Zeg: Hij is Allah, de Ene»"], "«Vandaag heb Ik jullie religie voor jullie vervolmaakt en Mijn gunst aan jullie voltooid.»"),
"sira_084": ("In welke stad stierf de Profeet ﷺ en werd hij begraven?", ["Medina", "Mekka", "Jeruzalem", "Ta'if"], "Hij stierf in Medina in het jaar 11 na de Hijra en werd daar begraven."),
"sira_085": ("In de kamer van welke echtgenote werd de Profeet ﷺ begraven?", ["Die van 'Aisha", "Die van Khadija", "Die van Hafsa", "Die van Umm Salama"], "Hij werd begraven waar hij stierf, in de kamer van 'Aisha, nu binnen de Moskee van de Profeet."),
"sira_086": ("Wie verklaarde bij de dood van de Profeet ﷺ: «Wie Muhammad aanbad, Muhammad is gestorven; wie Allah aanbidt, Allah is de Eeuwig Levende»?", ["Abu Bakr", "'Umar", "'Ali", "Bilal"], "Abu Bakr kalmeerde de metgezellen en reciteerde: «Muhammad is slechts een boodschapper…» (3:144)."),
"sira_087": ("Hoe heetten de twee kleinzonen van de Profeet ﷺ, de zonen van Fatima en 'Ali?", ["Al-Hasan en Al-Husayn", "Ibrahim en Isma'il", "Zayd en Usama", "Ja'far en 'Aqil"], "Al-Hasan en Al-Husayn, van wie de Profeet ﷺ innig hield."),
"sira_088": ("Welke vrouw van de Profeet ﷺ was de dochter van Abu Bakr?", ["'Aisha", "Hafsa", "Zaynab", "Sawda"], "'Aisha, dochter van Abu Bakr, heeft een zeer groot aantal hadiths overgeleverd."),
"sira_089": ("Welke vrouw van de Profeet ﷺ was de dochter van 'Umar ibn al-Khattab?", ["Hafsa", "'Aisha", "Umm Habiba", "Maymuna"], "Hafsa bint 'Umar; het eerste verzamelde exemplaar van de Koran werd bij haar bewaard."),
"sira_090": ("Welke metgezel leverde het grootste aantal hadiths van de Profeet ﷺ over?", ["Abu Hurayra", "Anas ibn Malik", "'Abdullah ibn 'Umar", "Jabir"], "Abu Hurayra, die de Profeet ﷺ voortdurend vergezelde, is de metgezel die de meeste hadiths overleverde."),
"sira_091": ("Welke jonge metgezel diende de Profeet ﷺ tien jaar zonder ooit een verwijt te horen?", ["Anas ibn Malik", "Usama ibn Zayd", "Ibn 'Abbas", "Zayd ibn Thabit"], "Anas zei: «Ik heb de Profeet ﷺ tien jaar gediend; hij zei nooit 'uff' tegen mij, noch 'waarom heb je dat gedaan?'»"),
"sira_092": ("Voor welke jonge neef bad de Profeet ﷺ: «O Allah, leer hem het Boek»?", ["'Abdullah ibn 'Abbas", "'Ali", "Ja'far", "Usama"], "De Profeet ﷺ omhelsde Ibn 'Abbas en zei: «O Allah, leer hem het Boek.»"),
"sira_093": ("Welke metgezel zond de Profeet ﷺ naar Jemen, met de opdracht eerst op te roepen tot de eenheid van Allah?", ["Mu'adh ibn Jabal", "Bilal", "Alleen Abu Musa", "Zayd ibn Haritha"], "«Je gaat naar een volk van het Boek: roep hen eerst op te getuigen dat er geen god is dan Allah…»"),
"sira_094": ("Welke metgezel noemde de Profeet ﷺ «de betrouwbare (amin) van deze gemeenschap»?", ["Abu 'Ubayda ibn al-Jarrah", "Abu Bakr", "'Uthman", "Khalid"], "«Elke gemeenschap heeft een betrouwbare, en de betrouwbare van deze gemeenschap is Abu 'Ubayda ibn al-Jarrah.»"),
"sira_095": ("Welke metgezel, een schrijver van de openbaring, kreeg van Abu Bakr de taak de Koran te verzamelen?", ["Zayd ibn Thabit", "Abu Hurayra", "Anas ibn Malik", "Salman"], "Na de slag bij al-Yamama gaf Abu Bakr Zayd ibn Thabit de taak de Koran te verzamelen."),
"sira_096": ("Onder welke kalief werden officiële exemplaren van de Koran naar de provincies gestuurd?", ["'Uthman ibn 'Affan", "Abu Bakr", "'Umar", "'Ali"], "'Uthman liet de mushaf kopiëren en stuurde een exemplaar naar elke provincie."),
"sira_097": ("Uit welk land kwam de metgezel Salman, «al-Farisi» genoemd?", ["Perzië", "Abessinië", "Byzantium", "Jemen"], "Salman al-Farisi, «de Pers», kwam uit Perzië op zoek naar de waarheid."),
"sira_098": ("Welke metgezel, afkomstig uit de Byzantijnse landen, wordt «ar-Rumi» genoemd?", ["Suhayb", "Bilal", "Salman", "Abu Dharr"], "Suhayb ar-Rumi groeide op onder de Byzantijnen voordat hij in Mekka de islam omhelsde."),
"sira_099": ("Hoe heet de moskee van de Profeet ﷺ in Medina?", ["Al-Masjid an-Nabawi", "Al-Masjid al-Haram", "Al-Masjid al-Aqsa", "Masjid Quba"], "De moskee die hij in Medina stichtte heet de Moskee van de Profeet, al-Masjid an-Nabawi."),
"sira_100": ("Hoe vaak komt de naam «Muhammad» voor in de Koran?", ["Vier keer", "Eén keer", "Twaalf keer", "Honderd keer"], "In de verzen 3:144, 33:40, 47:2 en 48:29; de naam «Ahmad» komt voor in 61:6."),
"sira_101": ("Hoe beschrijft de Koran de Profeet ﷺ voor de gelovigen, in vers 33:21?", ["Een uitstekend voorbeeld", "Een strenge rechter", "Een koning", "Een dichter"], "«Voorzeker, jullie hebben in de Boodschapper van Allah een uitstekend voorbeeld.»"),
"sira_102": ("Wat was de kunya (vaderlijke bijnaam) van de Profeet ﷺ?", ["Abu al-Qasim", "Abu Bakr", "Abu 'Abdullah", "Abu Talib"], "Hij werd Abu al-Qasim genoemd, naar zijn oudste zoon Al-Qasim."),
"sira_103": ("Hoe heette de zoon van de Profeet ﷺ die in Medina werd geboren en als klein kind stierf?", ["Ibrahim", "Al-Qasim", "'Abdullah", "Al-Hasan"], "Ibrahim, geboren in Medina, stierf als zuigeling; de Profeet ﷺ weende en zei dat het hart treurt zonder te zeggen wat Allah mishaagt."),
"sira_104": ("Voor wie leidde de Profeet ﷺ vóór de openbaring een handelskaravaan naar Syrië?", ["Khadija", "Abu Bakr", "Abu Sufyan", "Al-'Abbas"], "Khadija, een rijke koopvrouw, vertrouwde hem haar karavaan naar Syrië toe en deed hem daarna een huwelijksaanzoek."),
"sira_105": ("Hoe beslechtte de jonge Muhammad ﷺ het geschil tussen de clans over het terugplaatsen van de Zwarte Steen?", ["Hij legde hem op een doek die elke clan optilde, en plaatste hem daarna zelf", "Hij droeg hem alleen", "Hij lootte", "Hij vertrouwde hem toe aan Abu Bakr"], "Hij spreidde een mantel uit, legde de Steen erop, liet de clanhoofden de doek samen optillen en plaatste hem daarna eigenhandig."),
"sira_106": ("Op welke leeftijd ontving de Profeet ﷺ de eerste openbaring?", ["Veertig", "Vijfentwintig", "Vijftig", "Zestig"], "De openbaring begon toen hij veertig jaar oud was, in de grot Hira."),
"sira_107": ("Naar welke neef van Khadija, geleerd in de Schriften, werd de Profeet ﷺ na de eerste openbaring gebracht?", ["Waraqa ibn Nawfal", "Abu Talib", "Abu Lahab", "Al-Walid"], "Waraqa zei: «Dit is de Namus (de engel) die Allah naar Musa zond.»"),
"sira_108": ("Op welke heuvel klom de Profeet ﷺ om Quraysh openlijk op te roepen, na het vers «Waarschuw je naaste verwanten»?", ["As-Safa", "Uhud", "Arafat", "Hira"], "Hij klom op as-Safa, riep de clans van Quraysh en waarschuwde hen voor een zware straf."),
"sira_109": ("Welke kalief stelde de islamitische kalender in, beginnend bij het jaar van de Hijra?", ["'Umar ibn al-Khattab", "Abu Bakr", "'Uthman", "'Ali"], "Onder 'Umar werd de Hijra gekozen als beginpunt van de kalender."),
"sira_110": ("Hoeveel jaar leefde de Profeet ﷺ in Medina na de Hijra?", ["Tien", "Drie", "Twintig", "Dertien"], "Hij leefde tien jaar in Medina, van de Hijra tot zijn dood in het jaar 11 na de Hijra."),
"sira_111": ("Hoeveel jaar predikte de Profeet ﷺ in Mekka vóór de Hijra?", ["Dertien", "Drie", "Tien", "Drieëntwintig"], "Dertien jaar in Mekka, daarna tien in Medina: drieëntwintig jaar van missie."),
"sira_112": ("Welke metgezel, een dichter, verdedigde de Profeet ﷺ met zijn verzen en voor wie vroeg hij de steun van Jibril?", ["Hassan ibn Thabit", "Ka'b ibn Malik", "'Abdullah ibn Rawaha", "Labid"], "De Profeet ﷺ zei tegen Hassan: «Antwoord hun, en Jibril is met jou.»"),
"sira_113": ("Van welke metgezel zei de Profeet ﷺ dat hem «een van de fluiten van de familie van Dawud» was gegeven om zijn mooie recitatie?", ["Abu Musa al-Ash'ari", "Bilal", "Ubayy ibn Ka'b", "Ibn Mas'ud"], "Toen hij hem hoorde reciteren, zei de Profeet ﷺ dat Abu Musa een van de fluiten van de familie van Dawud was gegeven."),
"sira_114": ("De Profeet ﷺ raadde aan de Koran te leren van vier metgezellen. Wie van deze was er een van?", ["'Abdullah ibn Mas'ud", "Abu Hurayra", "Anas ibn Malik", "Khalid ibn al-Walid"], "«Leer de Koran van vier: Ibn Mas'ud, Salim, Mu'adh ibn Jabal en Ubayy ibn Ka'b.»"),
"sira_115": ("In welke slag raakte de Profeet ﷺ gewond in het gezicht en verloor hij een tand?", ["Uhud", "Badr", "Hunayn", "Khaybar"], "Bij Uhud brak zijn tand en raakte zijn gezicht gewond."),
"sira_116": ("Tegen welke metgezel, boogschutter bij Uhud, zei de Profeet ﷺ: «Schiet! Mogen mijn vader en moeder jouw losprijs zijn»?", ["Sa'd ibn Abi Waqqas", "Talha", "Az-Zubayr", "'Ali"], "De Profeet ﷺ reikte hem pijlen aan en zei: «Schiet, mogen mijn vader en moeder voor jou geofferd worden.»"),
"sira_117": ("Welke karavaan trokken de moslims uit om te onderscheppen, wat tot de slag bij Badr leidde?", ["Die van Abu Sufyan, terugkerend uit Syrië", "Die van de Negus", "Die van de Perzen", "Die van Ta'if"], "De karavaan van Quraysh onder leiding van Abu Sufyan ontkwam, maar het Mekkaanse leger kwam naar Badr."),
"sira_118": ("Wanneer omhelsde de Mekkaanse leider Abu Sufyan de islam?", ["Bij de verovering van Mekka", "Vóór de Hijra", "Bij Badr", "Na de dood van de Profeet ﷺ"], "Abu Sufyan bekeerde zich aan de vooravond van de intocht van de Profeet ﷺ in Mekka."),
"sira_119": ("Welke bron ontsprong voor Hajar en haar zoon Isma'il in de vallei van Mekka?", ["Zamzam", "De Nijl", "De Eufraat", "De Jordaan"], "Een engel sloeg op de grond en het water van Zamzam ontsprong; Hajar maakte er een kom omheen."),
"sira_120": ("Wat stond er gegraveerd op de ring van de Profeet ﷺ?", ["«Muhammad Rasul Allah»", "«Allahu Akbar»", "«La ilaha illa Allah»", "Alleen zijn naam"], "Zijn zilveren ring droeg «Muhammad, Boodschapper van Allah» in drie regels."),
"sira_121": ("Van welk voedsel hield de Profeet ﷺ, volgens 'Aisha?", ["Zoetigheden en honing", "Vis", "Sterke kruiden", "Alleen azijn"], "'Aisha vertelt dat de Profeet ﷺ van zoete dingen en honing hield."),
"sira_122": ("Op welke dag van de week werd de Profeet ﷺ geboren, een dag waarop hij ook vastte?", ["Maandag", "Vrijdag", "Zaterdag", "Woensdag"], "Gevraagd naar het vasten op maandag zei hij: «Dat is de dag waarop ik geboren ben en de dag waarop de openbaring tot mij kwam.»"),
"sira_123": ("Waar bevond zich het «zegel van het profeetschap» op het lichaam van de Profeet ﷺ?", ["Tussen zijn schouders", "Op zijn hand", "Op zijn voorhoofd", "Op zijn borst"], "Het zegel van het profeetschap bevond zich tussen zijn schouders."),
"sira_124": ("Van welk hout was de minbar (preekstoel) van de Profeet ﷺ gemaakt, door een timmerman?", ["Tamarisk (athl)", "Ceder", "Olijf", "Palm"], "De Profeet ﷺ liet een minbar van tamariskhout maken, van waaruit hij de mensen toesprak."),
"sira_125": ("Welke twee grote stammen van Medina vormden de Ansar?", ["De Aws en de Khazraj", "Quraysh en Thaqif", "Tamim en Hawazin", "Kinda en Hamdan"], "De Aws en de Khazraj, lange tijd rivalen, verenigden zich in de islam en werden de Ansar."),
"sira_126": ("Welke titel geeft de Koran aan de vrouwen van de Profeet ﷺ?", ["De Moeders van de Gelovigen", "De koninginnen van Medina", "De dochters van Quraysh", "De bewaarsters van het Boek"], "«Zijn vrouwen zijn hun moeders»: de Moeders van de Gelovigen."),
"sira_127": ("In welk jaar van de christelijke jaartelling vond de Hijra plaats?", ["622", "570", "632", "610"], "De Hijra, in 622, markeert het begin van de islamitische kalender."),
"sira_128": ("Wat antwoordde 'Abd ar-Rahman ibn 'Awf toen zijn Ansari-broeder hem de helft van zijn bezit aanbood?", ["«Wijs mij de markt»", "Hij nam alles aan", "Hij vroeg om een huis", "Hij weigerde te spreken"], "Hij zei: «Moge Allah jouw bezit en familie zegenen; wijs mij alleen de markt», en hij werd welvarend door handel."),
"sira_129": ("Aan welke metgezel vroeg de Profeet ﷺ welk vers van de Koran het grootste is, voordat hij hem feliciteerde met zijn antwoord (het Troonvers)?", ["Ubayy ibn Ka'b", "Abu Bakr", "Zayd ibn Thabit", "Bilal"], "Ubayy antwoordde: «Allah, er is geen god dan Hij, de Eeuwig Levende…»; de Profeet ﷺ zei: «Moge de kennis jou verheugen, Abu al-Mundhir!»"),
"sira_130": ("Hoe werd de plaats van de moskee van de Profeet ﷺ in Medina gekozen?", ["Waar zijn kameelmerrie knielde", "Door loting", "In het midden van de markt", "Op de berg Uhud"], "Hij liet zijn kameelmerrie vrij lopen: waar zij knielde, werd de moskee gebouwd."),
"sira_131": ("Hoeveel zonen had de Profeet ﷺ, die allen jong stierven?", ["Drie", "Eén", "Vijf", "Geen"], "Al-Qasim en 'Abdullah, geboren uit Khadija, en Ibrahim, geboren in Medina."),
"sira_132": ("Welke metgezel, door de Profeet ﷺ vrijgelaten en als een zoon opgevoed, was de vader van Usama?", ["Zayd ibn Haritha", "Bilal", "Salman", "'Ammar"], "Zayd ibn Haritha, geliefd bij de Profeet ﷺ, was de vader van Usama ibn Zayd."),
"sira_133": ("Welke jonge metgezel benoemde de Profeet ﷺ kort voor zijn dood tot aanvoerder van een leger, ondanks zijn jeugd?", ["Usama ibn Zayd", "Anas ibn Malik", "Ibn 'Abbas", "Ibn 'Umar"], "De Profeet ﷺ gaf Usama het bevel en antwoordde degenen die zijn leeftijd bekritiseerden dat hij het waard was, net als zijn vader."),
"sira_134": ("Welke grootvader van de Profeet ﷺ groef de put Zamzam, lang dichtgegooid, opnieuw uit?", ["'Abd al-Muttalib", "Hashim", "'Abd Manaf", "Qusayy"], "'Abd al-Muttalib groef Zamzam opnieuw uit en beheerde de put voor de pelgrims."),
"sira_135": ("Ongeveer hoeveel mensen vergezelden de Profeet ﷺ bij de slag bij Badr?", ["Iets meer dan driehonderd", "Tienduizend", "Duizend", "Vijftig"], "De moslims bij Badr waren iets meer dan driehonderd, tegenover een veel groter leger."),
"sira_136": ("In welke maand van de islamitische kalender werd de Profeet ﷺ geboren?", ["Rabi' al-Awwal", "Ramadan", "Muharram", "Dhul-Hijja"], "Hij werd geboren in de maand Rabi' al-Awwal, in het Jaar van de Olifant."),
"sira_137": ("In welke maand kwam de Profeet ﷺ tijdens de Hijra aan in Medina?", ["Rabi' al-Awwal", "Ramadan", "Muharram", "Rajab"], "Hij kwam in Rabi' al-Awwal aan in Medina, na een verblijf in Quba."),
"sira_138": ("Welk pact sloot Quraysh om de Banu Hashim, die de Profeet ﷺ beschermden, te isoleren?", ["Een boycot: geen handel of huwelijk met hen", "Een wapenstilstand van tien jaar", "Een verdeling van de Ka'ba", "Een militair bondgenootschap"], "Quraysh tekende een boycotpact, en de Banu Hashim werden jarenlang in een vallei opgesloten."),
"sira_139": ("Hoe begon de Profeet ﷺ zijn missie in Mekka, vóór de openbare oproep?", ["Door discreet zijn naaste kring op te roepen", "Met een leger", "Met een brief aan koningen", "Met een bedevaart"], "Hij riep eerst zijn familie en vrienden in het geheim op, voordat de oproep openbaar werd."),
"sira_140": ("Tussen welke twee heuvels rende Hajar op zoek naar water voor Isma'il?", ["As-Safa en Al-Marwa", "Uhud en Thawr", "Arafat en Mina", "Hira en Thawr"], "Zij rende zeven keer tussen as-Safa en al-Marwa: de oorsprong van de sa'y van de pelgrims."),
"sira_141": ("Over welke kleinzoon zei de Profeet ﷺ: «Deze zoon van mij is een sayyid; Allah zal door hem twee groepen moslims verzoenen»?", ["Al-Hasan", "Al-Husayn", "Usama", "Ibn 'Abbas"], "Al-Hasan ibn 'Ali verzoende later twee grote groepen moslims, zoals de Profeet ﷺ had voorspeld."),
"sira_142": ("Hoe heette de dochter van de Profeet ﷺ, moeder van Al-Hasan en Al-Husayn?", ["Fatima", "Zaynab", "Ruqayya", "Umm Kulthum"], "Fatima, vrouw van 'Ali, was de moeder van Al-Hasan en Al-Husayn."),
"sira_143": ("Wie was de oudste dochter van de Profeet ﷺ?", ["Zaynab", "Fatima", "Ruqayya", "Umm Kulthum"], "Zaynab was de oudste van de vier dochters van de Profeet ﷺ."),
"sira_144": ("Welke metgezel, een voormalige slaaf van Abessijnse afkomst, werd om zijn mooie stem als muezzin gekozen?", ["Bilal ibn Rabah", "Salman", "Suhayb", "Zayd"], "Bilal, vrijgekocht door Abu Bakr, werd de muezzin van de Profeet ﷺ."),
"sira_145": ("Over welke metgezel zei de Profeet ﷺ: «Als ik een boezemvriend (khalil) onder de mensen zou nemen, zou hij het zijn»?", ["Abu Bakr", "'Umar", "'Ali", "'Uthman"], "«Als ik een boezemvriend uit mijn gemeenschap zou nemen, zou ik Abu Bakr nemen, maar hij is mijn broeder en metgezel.»"),
"sira_146": ("Welke stad wordt samen met Mekka «al-Haramayn» genoemd, de twee heiligdommen?", ["Medina", "Jeruzalem", "Ta'if", "Damascus"], "Mekka en Medina zijn de twee heilige steden, al-Haramayn."),
"sira_147": ("Hoe vaak verrichtte de Profeet ﷺ de Hajj na de Hijra?", ["Eén keer, de Afscheidsbedevaart", "Drie keer", "Elk jaar", "Nooit"], "Hij verrichtte slechts één Hajj na de Hijra: de Afscheidsbedevaart, in het jaar 10 na de Hijra."),
"sira_148": ("Wat deed de Profeet ﷺ volgens Anas toen een bedoeïen hard aan zijn mantel trok en om goederen vroeg?", ["Hij glimlachte en beval dat hem iets gegeven werd", "Hij liet hem straffen", "Hij vertrok zonder een woord", "Hij joeg hem weg"], "De Profeet ﷺ draaide zich naar hem om, lachte en beval dat hem iets gegeven werd."),
"sira_149": ("Welke stad, waar de al-Aqsa-moskee staat, was de bestemming van de Nachtreis?", ["Jeruzalem", "Damascus", "Caïro", "Bagdad"], "De Nachtreis bracht de Profeet ﷺ van Mekka naar de al-Aqsa-moskee in Jeruzalem."),
"sira_150": ("Hoe oud was de Profeet ﷺ toen hij stierf?", ["Drieënzestig", "Veertig", "Vijftig", "Tachtig"], "Hij stierf op drieënzestigjarige leeftijd, in het jaar 11 na de Hijra."),
}
